<?php $company=query("SELECT u.id,u.* FROM euser u WHERE u.id=? AND u.role='employer'",[(int)($_GET['id']??0)])->fetch();if(!$company):http_response_code(404);?><section class="page"><h1>Company unavailable.</h1></section><?php else:?><section class="page"><a href="jsearch.php">← Find a job</a><h1><?=h($company['company_name'])?></h1><p>Employer ID: HST-<?=h($company['id'])?> · <?=h($company['location'])?></p><div class="description"><?=nl2br(h($company['bio']))?></div><?php if($company['website']&&in_array(strtolower(parse_url($company['website'],PHP_URL_SCHEME)??''),['http','https'],true)):?><a class="text-link" href="<?=h($company['website'])?>" target="_blank" rel="noopener noreferrer">Company website ↗</a><?php endif;?><h2>Open opportunities</h2><?php $roles=query('SELECT * FROM eprofile WHERE employer_id=? ORDER BY id DESC',[$company['id']])->fetchAll();if(!$roles):?><p>No open roles right now.</p><?php endif;foreach($roles as $role)jobrow($role);?></section><?php endif;?>
